const filter = ref('すべて')
const usage = ref('home')
const activeUsage = computed(() => usageGuides.find(g => g.id === usage.value)!)
const filtered = computed(() => products.filter(p => p.title.toLowerCase().includes(query.value.trim().toLowerCase()) && (filter.value === 'すべて' || (filter.value === '新品' ? p.condition.startsWith('新品') : p.condition === filter.value))))
const compared = computed(() => products.filter(p => selected.value.includes(p.id)))
const rows = [{key:'price',label:'参考価格（税込）'},{key:'cpu',label:'CPU'},{key:'memory',label:'メモリ'},{key:'ssd',label:'ストレージ'},{key:'display',label:'画面'},{key:'weight',label:'重量'},{key:'condition',label:'状態'},{key:'office',label:'Office'},{key:'warranty',label:'保証'}] as const
usePageSeo('大学生のノートパソコンの選び方｜新品・中古12商品を比較', '大学生のノートパソコン選びを、大学指定の推奨環境、持ち運び、Office、予算から解説。新品・中古の12商品を画面・メモリ・参考価格で比較し、購入前の確認事項を整理します。', '/')
